-- ⚠ CORREÇÃO (25/09/2026): NAO RODAR ESTE ARQUIVO.
-- Ele foi substituido pela importacao completa (packages/db/scripts/importar-legado.mjs),
-- que ja gravou as 10.864 vendas do sistema antigo nas tabelas vendas/pagamentos.
-- Rodar este arquivo agora faria o financeiro do sistema antigo contar DUAS VEZES
-- na view financeiro_entradas.
-- ============================================================================
-- Adega Dois Irmaos -- FINANCEIRO DO SISTEMA ANTIGO (Firebird) -> banco novo
-- Gerado em 25/09/2026 a partir do banco final do sistema antigo
-- (legado/DADOS_sistema_antigo_final_2026-09-25.zip).
--
-- O que faz: cria uma TABELA A PARTE (financeiro_legado) com TODOS os
-- recebimentos de vendas finalizadas do sistema antigo (21/03/2025 a
-- 24/09/2026), uma linha por forma de pagamento, e uma VIEW
-- (financeiro_entradas) que junta isso com os recebimentos do sistema novo.
-- NAO mexe em vendas, produtos nem estoque do sistema novo.
-- Pode rodar mais de uma vez: nao duplica (chave = codigo do pagamento antigo).
--
-- Linhas: 11301  |  Total liquido (valor - troco): R$ 234,360.12
-- Rodar no Railway: Postgres -> Data -> Query (cole o arquivo inteiro).
-- ============================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS financeiro_legado (
  pagamento_codigo integer PRIMARY KEY,   -- VENDAS_FPG.CODIGO no sistema antigo
  venda_codigo     integer NOT NULL,      -- VENDAS_MASTER.CODIGO no sistema antigo
  data             date    NOT NULL,      -- sistema antigo nao guardava hora
  total_venda      numeric(15,2) NOT NULL,
  forma            text    NOT NULL,      -- dinheiro, pix, debito, credito, a_prazo, troca
  valor            numeric(15,2) NOT NULL,
  troco            numeric(15,2) NOT NULL DEFAULT 0,
  liquido          numeric(15,2) GENERATED ALWAYS AS (valor - troco) STORED,
  origem           text    NOT NULL DEFAULT 'sistema_antigo',
  importado_em     timestamptz NOT NULL DEFAULT now()
);

ON CONFLICT (pagamento_codigo) DO NOTHING;

-- Entradas unificadas: sistema antigo + sistema novo (vendas pagas).
-- Valores em REAIS. Dia do sistema novo no fuso da loja (Brasilia).
CREATE OR REPLACE VIEW financeiro_entradas AS
  SELECT data, forma, liquido AS valor, origem, venda_codigo::text AS venda_ref
  FROM financeiro_legado
  UNION ALL
  SELECT (v.ocorrido_em AT TIME ZONE 'America/Sao_Paulo')::date AS data,
         p.forma::text AS forma,
         round((p.valor - p.troco) / 100.0, 2) AS valor,
         'sistema_novo' AS origem,
         v.id::text AS venda_ref
  FROM pagamentos p
  JOIN vendas v ON v.id = p.venda_id
  WHERE v.status = 'paga';

COMMIT;

-- CONFERENCIA (so leitura): total por mes e origem.
SELECT to_char(data, 'YYYY-MM') AS mes, origem, count(*) AS lancamentos, sum(valor) AS total
FROM financeiro_entradas
GROUP BY 1, 2
ORDER BY 1, 2;
